function maximumSumOfHeights(maxHeights) {
  const n = maxHeights.length;
  const left = new Array(n).fill(0);
  const right = new Array(n).fill(0);

  let stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && maxHeights[stack[stack.length - 1]] > maxHeights[i]) {
      stack.pop();
    }
    const j = stack.length > 0 ? stack[stack.length - 1] : -1;
    const before = j >= 0 ? left[j] : 0;
    left[i] = before + maxHeights[i] * (i - j);
    stack.push(i);
  }

  stack = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length > 0 && maxHeights[stack[stack.length - 1]] > maxHeights[i]) {
      stack.pop();
    }
    const j = stack.length > 0 ? stack[stack.length - 1] : n;
    const after = j < n ? right[j] : 0;
    right[i] = after + maxHeights[i] * (j - i);
    stack.push(i);
  }

  let best = 0;
  for (let i = 0; i < n; i++) {
    best = Math.max(best, left[i] + right[i] - maxHeights[i]);
  }
  return best;
}

