function maximumSumOfHeights(maxHeights) {
  // Try every peak: it takes its full height, and each tower further out is capped by its neighbour toward the peak.
  const n = maxHeights.length;
  let best = 0;
  for (let peak = 0; peak < n; peak++) {
    let total = maxHeights[peak];
    let cap = maxHeights[peak];
    for (let x = peak - 1; x >= 0; x--) {
      cap = Math.min(cap, maxHeights[x]);
      total += cap;
    }
    cap = maxHeights[peak];
    for (let x = peak + 1; x < n; x++) {
      cap = Math.min(cap, maxHeights[x]);
      total += cap;
    }
    best = Math.max(best, total);
  }
  return best;
}

