function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' || rand() < 0.3 ? 1000000000 : 6;
  const value = () => 1 + Math.floor(rand() * top);
  const shape = Math.floor(rand() * 4);
  let maxHeights = Array.from({ length: n }, value);
  if (shape === 1) maxHeights.sort((a, b) => a - b);
  if (shape === 2) {
    // A valley: falling then rising, which makes the stacks pop a lot.
    maxHeights.sort((a, b) => b - a);
    const cut = Math.floor(rand() * (n + 1));
    maxHeights = [...maxHeights.filter((_, i) => i % 2 === 0), ...maxHeights.filter((_, i) => i % 2 === 1).reverse()];
    maxHeights = [...maxHeights.slice(cut), ...maxHeights.slice(0, cut)];
  }
  if (shape === 3) {
    // Few distinct heights so that equal values meet on the stacks.
    const levels = Array.from({ length: 3 }, value);
    maxHeights = maxHeights.map(() => levels[Math.floor(rand() * levels.length)]);
  }
  return [maxHeights];
}
